def bib_escape(s):
    return s

entries=[]
for s in sources:
    fields={"author":s["authors"], "title":s["title"], "year":s["year"], "url":s["url"]}
    for k in ("journal","volume","number","pages","publisher","series","doi","eprint","archivePrefix"):
        if k in s: fields[k]=s[k]
    fields["note"]="Verified: primary text actually opened on 18 November 2026. "+s["location"]+". "+s.get("note_extra", "")
    fields["keywords"]="verified"
    entries.append("@"+s["kind"]+"{"+s["key"]+",\n"+"\n".join("  "+k+" = {"+bib_escape(v)+"}," for k,v in fields.items())+"\n}\n")
(ROOT/"arithmetic_references.bib").write_text("\n".join(entries))

with (ROOT/"arithmetic_sources.tsv").open("w",newline="") as f:
    fields=["key","authors","year","title","url","location","use","detail","local","opened_date","opened_by","verification"]
    w=csv.DictWriter(f,fields,delimiter="\t",extrasaction="ignore");w.writeheader()
    for s in sources:w.writerow(dict(s,opened_date=DAY,opened_by=ACTOR,verification="Primary text opened; stated locations and hypotheses matched. No human verification claimed."))

